/**
 * A raw crafting ingredient harvested from the world, such as ore,
 * timber, hides, or arcane crystals. Materials are consumed during
 * crafting recipes to produce finished goods.
 */
export type GatherSource = 'mining' | 'herbalism' | 'logging' | 'skinning' | 'excavation' | 'prospecting' | 'weaving' | 'salvage' | 'hunting';

export interface MaterialDef {
    name: string;
    tier: number;
    desc?: string;
    gatherDifficulty: number;
    gatherSource: GatherSource;
}

/**
 * The physical state of an item, ranging from pristine to ruined.
 * Condition affects resale value and mechanical effectiveness.
 */
export interface ConditionDef {
    name: string;
    tier: number;
}

